files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --focus: #ffd166;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.06) 1px, transparent 1px);
  background-size: 16px 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.board {
  width: 100%;
  max-width: 400px;
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 12px;
  padding: 24px 20px;
  text-align: center;
  box-shadow: 0 8px 0 rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 16px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.coin {
  width: 96px;
  height: 96px;
  margin: 0 auto 16px;
  display: grid;
  place-items: center;
  font-size: 2.5rem;
  font-weight: bold;
  background: var(--bg);
  border: 4px solid var(--muted);
  border-radius: 50%;
  transition: transform 0.15s ease, border-color 0.15s ease;
}

.coin.heads {
  border-color: var(--focus);
  color: var(--focus);
}

.coin.tails {
  border-color: var(--accent-hover);
  color: var(--accent-hover);
}

.coin.flipping {
  transform: rotateY(180deg);
}

.result {
  font-size: 1.1rem;
  margin: 0 0 20px;
  min-height: 1.4em;
  color: var(--muted);
}

.stats {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 24px;
}

.stat {
  flex: 1;
  background: var(--bg);
  border-radius: 8px;
  padding: 10px 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.stat-value {
  font-size: 1.4rem;
  font-weight: bold;
}

.stat-sub {
  font-size: 0.7rem;
  color: var(--muted);
  min-height: 1em;
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  font: inherit;
  font-weight: bold;
  padding: 14px 12px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  color: var(--bg);
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.1s ease;
  box-shadow: 0 4px 0 rgba(0,0,0,0.4);
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: var(--accent-hover);
}

.btn.secondary {
  background: var(--muted);
  color: var(--bg);
}

.btn.secondary:hover {
  background: #c0c0d0;
}

.btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 rgba(0,0,0,0.4);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 360px) {
  .board {
    padding: 16px 12px;
  }
  .coin {
    width: 80px;
    height: 80px;
    font-size: 2rem;
  }
  .stat-value {
    font-size: 1.2rem;
  }
}

const coinEl = document.getElementById('coin');
const resultEl = document.getElementById('result');
const headsEl = document.getElementById('heads');
const tailsEl = document.getElementById('tails');
const streakEl = document.getElementById('streak');
const streakSideEl = document.getElementById('streakSide');
const flipBtn = document.getElementById('flipBtn');
const resetBtn = document.getElementById('resetBtn');

let heads = 0;
let tails = 0;
let streak = 0;
let lastSide = null;

function updateDisplay() {
  headsEl.textContent = heads;
  tailsEl.textContent = tails;
  streakEl.textContent = streak;
  streakSideEl.textContent = lastSide ? lastSide : '';
}

function flip() {
  const side = Math.random() < 0.5 ? 'heads' : 'tails';

  if (side === 'heads') {
    heads++;
  } else {
    tails++;
  }

  if (side === lastSide) {
    streak++;
  } else {
    streak = 1;
    lastSide = side;
  }

  resultEl.textContent = side === 'heads' ? 'Heads!' : 'Tails!';
  coinEl.textContent = side === 'heads' ? 'H' : 'T';
  coinEl.className = 'coin ' + side;

  // brief flip animation
  coinEl.classList.add('flipping');
  setTimeout(() => coinEl.classList.remove('flipping'), 150);

  updateDisplay();
}

function reset() {
  heads = 0;
  tails = 0;
  streak = 0;
  lastSide = null;
  resultEl.textContent = 'Flip to start';
  coinEl.textContent = '?';
  coinEl.className = 'coin';
  updateDisplay();
}

flipBtn.addEventListener('click', flip);
resetBtn.addEventListener('click', reset);

updateDisplay();
